 10→func TestParseHookEvent_SessionStart(t *testing.T) {
 11→	t.Parallel()
 12→
 13→	ag := &FactoryAIDroidAgent{}
 14→	input := `{"session_id": "test-session", "transcript_path": "/tmp/transcript.jsonl"}`
 15→
 16→	event, err := ag.ParseHookEvent(HookNameSessionStart, strings.NewReader(input))
 17→	if err != nil {
 18→		t.Fatalf("unexpected error: %v", err)
 19→	}
 20→	if event == nil {
 21→		t.Fatal("expected event, got nil")
 22→	}
 23→	if event.Type != agent.SessionStart {
 24→		t.Errorf("expected SessionStart, got %v", event.Type)
 25→	}
 26→	if event.SessionID != "test-session" {
 27→		t.Errorf("expected session_id 'test-session', got %q", event.SessionID)
 28→	}
 29→	if event.SessionRef != "/tmp/transcript.jsonl" {
 30→		t.Errorf("expected transcript_path '/tmp/transcript.jsonl', got %q", event.SessionRef)
 31→	}
 32→}
