 52→// TestParseHookEvent_TurnStart_SessionStartFormat verifies that parseTurnStart
 53→// handles SessionStart-format stdin (no "prompt" field). This happens when
 54→// user-prompt-submit is installed on the SessionStart event type to ensure
 55→// TurnStart fires in droid exec mode.
 56→func TestParseHookEvent_TurnStart_SessionStartFormat(t *testing.T) {
 57→	t.Parallel()
 58→
 59→	ag := &FactoryAIDroidAgent{}
 60→	// SessionStart-format stdin: only session_id and transcript_path, no prompt
 61→	input := `{"session_id": "exec-sess", "transcript_path": "/tmp/exec.jsonl"}`
 62→
 63→	event, err := ag.ParseHookEvent(HookNameUserPromptSubmit, strings.NewReader(input))
 64→	if err != nil {
 65→		t.Fatalf("unexpected error: %v", err)
 66→	}
 67→	if event.Type != agent.TurnStart {
 68→		t.Errorf("expected TurnStart, got %v", event.Type)
 69→	}
 70→	if event.SessionID != "exec-sess" {
 71→		t.Errorf("expected session_id 'exec-sess', got %q", event.SessionID)
 72→	}
 73→	if event.SessionRef != "/tmp/exec.jsonl" {
 74→		t.Errorf("expected transcript_path '/tmp/exec.jsonl', got %q", event.SessionRef)
 75→	}
 76→	if event.Prompt != "" {
 77→		t.Errorf("expected empty prompt, got %q", event.Prompt)
 78→	}
 79→}
