  87→func TestParseDroidTranscriptFromBytes_StartLineSkipsNonMessageEntries(t *testing.T) {
  88→	t.Parallel()
  89→
  90→	// Transcript: session_start(0), message(1), session_event(2), message(3), message(4)
  91→	// Raw line indices:  0            1            2                3            4
  92→	data := []byte(
  93→		`{"type":"session_start","id":"s1"}` + "\n" +
  94→			`{"type":"message","id":"m1","message":{"role":"user","content":"hello"}}` + "\n" +
  95→			`{"type":"session_event","data":"some event"}` + "\n" +
  96→			`{"type":"message","id":"m2","message":{"role":"assistant","content":"hi"}}` + "\n" +
  97→			`{"type":"message","id":"m3","message":{"role":"user","content":"bye"}}` + "\n",
  98→	)
  99→
 100→	// With startLine=0, all 3 messages should be returned
 101→	allLines, err := ParseDroidTranscriptFromBytes(data, 0)
