 107→	}
 108→
 109→	// With startLine=2, skip raw lines 0-1 (session_start + m1).
 110→	// Lines 2 (session_event) is skipped by filter, lines 3-4 (m2, m3) are messages.
 111→	fromLine2, err := ParseDroidTranscriptFromBytes(data, 2)
 112→	if err != nil {
 113→		t.Fatalf("ParseDroidTranscriptFromBytes(2) error = %v", err)
