 538→	// 0: user message 1
 539→	// 1: assistant response 1 (100/50 tokens)
 540→	// 2: user message 2
 541→	// 3: assistant response 2 (200/100 tokens)
 542→	// 4: user message 3
 543→	// 5: assistant response 3 (300/150 tokens)
 544→
 545→	// Droid format: outer type is always "message", role is inside the inner message
 546→	transcriptContent := []byte(
 547→		`{"type":"message","id":"u1","message":{"role":"user","content":"first prompt"}}` + "\n" +
 548→			`{"type":"message","id":"a1","message":{"role":"assistant","id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
 549→			`{"type":"message","id":"u2","message":{"role":"user","content":"second prompt"}}` + "\n" +
