 551→			`{"type":"message","id":"u3","message":{"role":"user","content":"third prompt"}}` + "\n" +
 552→			`{"type":"message","id":"a3","message":{"role":"assistant","id":"m3","usage":{"input_tokens":300,"output_tokens":150}}}` + "\n",
 553→	)
 554→	if err := os.WriteFile(transcriptPath, transcriptContent, 0o600); err != nil {
 555→		t.Fatalf("failed to write transcript: %v", err)
 556→	}
 557→
 558→	// Test 1: From line 0 - all 3 turns = 600 input, 300 output
