1108→	// Subagent transcript: assistant message with its own tokens
1109→	writeJSONLFile(t, subagentsDir+"/agent-sub99.jsonl",
1110→		makeAssistantTokenLine(t, "sa1", "msg_sub1", 200, 80),
1111→		makeAssistantTokenLine(t, "sa2", "msg_sub2", 150, 60),
1112→	)
1113→
1114→	usage, err := CalculateTotalTokenUsageFromTranscript(transcriptPath, 0, subagentsDir)
1115→	if err != nil {
1116→		t.Fatalf("CalculateTotalTokenUsageFromTranscript() error: %v", err)
1117→	}
1118→
1119→	// Main agent: 100 input, 50 output, 1 API call
1120→	if usage.InputTokens != 100 {
1121→		t.Errorf("main InputTokens = %d, want 100", usage.InputTokens)
1122→	}
1123→	if usage.OutputTokens != 50 {
1124→		t.Errorf("main OutputTokens = %d, want 50", usage.OutputTokens)
1125→	}
1126→	if usage.APICallCount != 1 {
1127→		t.Errorf("main APICallCount = %d, want 1", usage.APICallCount)
1128→	}
1129→
1130→	// Subagent tokens should be aggregated
1131→	if usage.SubagentTokens == nil {
1132→		t.Fatal("SubagentTokens is nil, expected subagent token data")
1133→	}
1134→	if usage.SubagentTokens.InputTokens != 350 {
1135→		t.Errorf("subagent InputTokens = %d, want 350 (200+150)", usage.SubagentTokens.InputTokens)
1136→	}
1137→	if usage.SubagentTokens.OutputTokens != 140 {
1138→		t.Errorf("subagent OutputTokens = %d, want 140 (80+60)", usage.SubagentTokens.OutputTokens)
1139→	}
1140→	if usage.SubagentTokens.APICallCount != 2 {
1141→		t.Errorf("subagent APICallCount = %d, want 2", usage.SubagentTokens.APICallCount)
1142→	}
1143→}
